WITH lines AS (SELECT id, effective_from, currency, val FROM price_tiers LATERAL VIEW EXPLODE(tier_prices) t AS val), with_windows AS (SELECT *, MIN(val) OVER w_running currency_min_val, PERCENT_RANK() OVER (PARTITION BY currency ORDER BY val DESC NULLS LAST) val_percent_rank, AVG(val) OVER w_running currency_avg_val FROM lines WINDOW w_running AS (PARTITION BY currency)), base AS (SELECT *, CAST(val AS INT) val_int FROM with_windows WHERE val > 52), metrics AS (SELECT id, effective_from, val, currency_min_val, val_percent_rank, currency_avg_val, val_int, CUME_DIST() OVER (PARTITION BY currency ORDER BY val_percent_rank DESC) val_percent_rank_cume_dist FROM base) SELECT DATE_TRUNC('MONTH', effective_from) AS activity_month, CASE WHEN val_percent_rank_cume_dist >= 0.69 THEN 'PREMIUM' ELSE 'STANDARD' END AS val_percent_rank_cume_dist_tier, ROUND(AVG(val_int), 2) AS avg_val_int, COUNT(DISTINCT id) AS distinct_ids, MIN(val) AS min_val, ROUND(AVG(currency_min_val), 2) AS avg_currency_min_val, MIN(currency_min_val) AS min_currency_min_val, PERCENTILE_APPROX(val_percent_rank, ARRAY(0.25, 0.5, 0.75)) AS val_percent_rank_quartiles FROM metrics GROUP BY DATE_TRUNC('MONTH', effective_from), CASE WHEN val_percent_rank_cume_dist >= 0.69 THEN 'PREMIUM' ELSE 'STANDARD' END;
